mapper.select:
select p.plan_id, p.plan_name, p.cron_expression, p.job_id, p.report_style, p.status, p.create_by, p.create_time, p.update_by, p.update_time, p.remark, (select count(1) from sup_tim_inspection_plan_item i where i.plan_id = p.plan_id and i.enabled_flag = 'Y') as item_count, (select count(1) from sup_tim_inspection_plan_target t where t.plan_id = p.plan_id) as target_count from sup_tim_inspection_plan p
and p.plan_name like concat('%', #{planName}, '%') and p.status = #{status} and p.report_style = #{reportStyle}
order by p.plan_id desc

mapper.insert:
insert into sup_tim_inspection_plan(
    plan_name, cron_expression, job_id, report_style, status,
    create_by, create_time, update_by, update_time, remark
) values (
    #{planName}, #{cronExpression}, #{jobId}, #{reportStyle}, #{status},
    #{createBy}, #{createTime}, #{updateBy}, #{updateTime}, #{remark}
)

mapper.update:
update sup_tim_inspection_plan
plan_name = #{planName}, cron_expression = #{cronExpression}, job_id = #{jobId}, report_style = #{reportStyle}, status = #{status}, update_by = #{updateBy}, update_time = #{updateTime}, remark = #{remark},
where plan_id = #{planId}

update sup_tim_inspection_plan
set job_id = #{jobId}
where plan_id = #{planId}

update sup_tim_inspection_plan
set status = #{status}, update_by = #{updateBy}, update_time = sysdate()
where plan_id = #{planId}

mapper.insert:
insert into sup_tim_inspection_plan_item(
    plan_id, item_code, item_name, item_type, enabled_flag, sort_order,
    threshold_value, threshold_unit, compare_rule, time_window_minutes, timeout_seconds,
    create_by, create_time, update_by, update_time, remark
) values (
    #{planId}, #{itemCode}, #{itemName}, #{itemType}, #{enabledFlag}, #{sortOrder},
    #{thresholdValue}, #{thresholdUnit}, #{compareRule}, #{timeWindowMinutes}, #{timeoutSeconds},
    #{createBy}, #{createTime}, #{updateBy}, #{updateTime}, #{remark}
)

mapper.select:
select plan_target_id, plan_id, item_code, target_id
from sup_tim_inspection_plan_target
where plan_id = #{planId}
